def _una(arg):
    v, m, s = arg
    return dict(B.partida("cuerpo", s, cultura=cultura(m), mando=m, **VARS[v]), tipo="cuerpo", variante=v, mando=m, semilla=s)


def _igual(s): return B.partida("cuerpo", s, cultura=os.path.join(AQUI, "cultura_valle_medio.json"), mando="medio", cfg_mundo=CFG_ANTES, anticipa=True)


if __name__ == "__main__":
    if sys.argv[1] == "igualdad":
        with Pool(3) as P: res = P.map(_igual, [1, 2, 3])
        A6 = {r["semilla"]: r for r in json.load(open(os.path.join(AQUI, "banco_v6.json"))) if r["variante"] == "COMPLETA3" and r["mando"] == "medio"}
        dif = {}
        for s, r in zip((1, 2, 3), res):
            v = json.loads(json.dumps(A6[s])); n_ = json.loads(json.dumps(r))
            d = [k for k in v if k not in ("tipo", "variante", "mando", "semilla") and v[k] != n_.get(k)]
            if d: dif[s] = d
        out = {"partidas": len(res), "config_mundo": os.path.relpath(CFG_ANTES, RAIZ), "diferencias": dif, "identico": not dif}
        json.dump(out, open(os.path.join(AQUI, "igualdad_v7.json"), "w"), ensure_ascii=False, indent=1); print(out["identico"], dif)
    elif sys.argv[1] == "piezas":                                           # v7 + cada pieza de la v7b, con peligro medio -> banco_v7_piezas.json
        with Pool(8) as P: res = P.map(_una, [(v, "medio", s) for v in ("V7R", "V7N") for s in B.SEMILLAS], chunksize=1)
        json.dump(res, open(os.path.join(AQUI, "banco_v7_piezas.json"), "w"), ensure_ascii=False, indent=1)
        for v in ("V7R", "V7N"): print(v, sum(8 - len(r["muertes"]) for r in res if r["variante"] == v))
    else:
        trabajos = [(v, m, s) for v in ("V7", "V7B", "COMPLETA3") for m in MANDOS for s in B.SEMILLAS]
        with Pool(8) as P: res = P.map(_una, trabajos, chunksize=1)
        json.dump(res, open(os.path.join(AQUI, "banco_v7.json"), "w"), ensure_ascii=False, indent=1)
        for v in ("COMPLETA3", "V7", "V7B"):
            print(v, {m: sum(8 - len(r["muertes"]) for r in res if r["variante"] == v and r["mando"] == m) for m in MANDOS})
